"use strict";(self.webpackChunkwebsite=self.webpackChunkwebsite||[]).push([[6139],{90580:e=>{e.exports=JSON.parse('{"tag":{"label":"off-chain","permalink":"/docs/tags/off-chain","allTagsPath":"/docs/tags","count":8,"items":[{"id":"compute/architecture","title":"Architecture","description":"What follows is a summary of the architecture and the components that are involved in running a Cartesi Compute Application, meaning some dApp that makes use of our SDK. It is convenient to start with the description of the typical ingredients involved in a decentralized application. Namely, the blockchain node and the client software.","permalink":"/docs/compute/architecture"},{"id":"compute/drives","title":"Drives","description":"This section describes in detail the Drive[] _inputDrives parameter of the instantiate call.","permalink":"/docs/compute/drives"},{"id":"compute/how","title":"How it works","description":"Cartesi Compute SDK allows Cartesi dApps to specify and request verifiable computations to Cartesi Machines. Additionally, the SDK provides tools to facilitate and reduce the cost of inputting data into Cartesi Machines.","permalink":"/docs/compute/how"},{"id":"compute/instantiate","title":"Instantiate","description":"This section describes the main ingredient of the on-chain Cartesi Compute infrastructure.","permalink":"/docs/compute/instantiate"},{"id":"compute/machine-offchain","title":"Machines off-chain","description":"Although an extensive documentation of Cartesi Machines can be found here, one may choose to skip this reading and jump right away to their usage inside the blockchain through Cartesi Compute. For that, it is enough to regard a Cartesi Machine as a black box that executes computations.","permalink":"/docs/compute/machine-offchain"},{"id":"compute/overview","title":"Overview","description":"Cartesi Compute allows you to implement a function in which you receive a set of inputs and it provides an output. So you can think of a Compute dApp as a computational oracle that tells you the result of a computation.","permalink":"/docs/compute/overview"},{"id":"compute/provider","title":"Provider drives","description":"After going through the last section, the reader is already able to specify drives if the data was available to the caller at the time of instantiation.","permalink":"/docs/compute/provider"},{"id":"compute/off-chain-api","title":"The off-chain API","description":"After the call for instantiate, the blockchain may already have all information that is necessary to execute the machine. But in many cases it also needs to get input from other users. In a game for example, the user may need to insert their decisions on input drives for later processing.","permalink":"/docs/compute/off-chain-api"}],"unlisted":false}}')}}]);